INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l13',4,3,13,'The Search for Oil','探寻石油','最高级(the deepest…of all)+ as much as、被动语态各式(is raised / are lowered / is rotated / must be kept)、Once 引导的时间状语从句、介词 + 关系代词(from which / by means of which)、want sb/sth to do + until 从句(NCE4 无 KS 页,考点由课文结构自取;IP:源为 T.F.加斯克尔科普著作,内容为通用钻油技术事实(不可版权),已用 100% 原创行文复述,无人物;题材=钻探石油的原理与过程·无害;美语化 meter/endeavor;第四册第13课·第三单元开工)','在矿工往地下钻的所有孔洞里,为找石油而打的那些是最深的;有的深达两万五千英尺。可是,与为煤或别的矿藏挖的竖井不同,这些孔从来不是要把人送下地底的。它们只是窄窄的钻孔,直径不到一英尺;正是这场找油的追逐,把深钻的技艺推得比任何别的采矿都远。地质学家一旦决定在哪里钻,一座高高的钢塔——井架——便被竖立在那地点之上。它必须立得高,因为它像一套巨大的滑轮组:一根根长长的钻管从它上面被放入地下,过后又被拽出来。钻管由顶端一台大功率发动机带动旋转,底部装着一枚硬硬的钻头,咬进岩石。因为钻井队必须确切知道钻头钻到了哪些岩层,他们时不时用一枚特制的取芯钻头取一块样本;它切出一段干净的岩柱,从这段岩芯里,可以清楚地读出钻头一路穿过的地层。钻头一旦钻进油层,油往往会自己涌向地面,因为它下方的水或天然气以巨大的压力把它顶着。那压力必须被牢牢控制住;控制的办法,是让沉重的泥浆在钻管里循环流下。今天谁也不想要那种老式而浪漫的井喷——把油高高喷向空中——因为那样一柱冲天只会白白浪费油和气。工程师们希望油乖乖待在井里,直到能以他们所选定的方式,安安静静、稳稳当当地把它引出来。','{"q":"Listen and answer — What do oilmen want to achieve as soon as they strike oil?","options":["To keep the oil under control and prevent a wasteful gusher","To let the oil spout as high as possible","To sell the well immediately","To fill the hole with water"],"answer_index":0}'::jsonb,'{"title":"最高级 + as much as / 被动语态 / Once 从句 / 介词+关系代词 / want sth to do","intro":"①最高级 the deepest … of all;as much as 25,000 feet(多达)。②被动语态:a derrick is raised;pipe is rotated;pressure must be kept under control。③Once 引导时间从句‘一…就’:Once the bit breaks into the oil, …。④介词 + 关系代词:a cylinder from which the strata can be read;the mud by means of which they control it。⑤want sb/sth to do + until 从句:want the oil to stay down until it can be led off。","table":{"headers":["用法","结构","例子"],"rows":[["最高级","the + 最高级 + of all","the deepest holes of all"],["被动语态","be + 过去分词","the pipe is rotated by an engine"],["Once 从句","Once + 从句, 主句","Once the bit breaks in, oil rushes up"],["介词+关系代词","介词 + which","a cylinder from which the strata can be read"],["want sth to do","want sb/sth to do","want the oil to stay down the hole"]]},"specialRules":[{"rule":"as much as + 数量 表示‘多达、达…之多’,强调数量之大。","mark":"as much as 25,000 feet"},{"rule":"情态动词的被动:must be kept、can be led off = 情态词 + be + 过去分词。","mark":"must be kept / can be led off"},{"rule":"美式拼写:meter(米,英式 metre)、endeavor(努力,英式 endeavour)。本课已按美语写。","mark":"meter / endeavor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l13',1,NULL,'Of all the holes that miners drill into the earth, those sunk in the search for oil are the deepest of all; some reach down as much as twenty-five thousand feet. Yet, unlike the shafts cut for coal or other mineral deposits, these holes are never meant to carry men underground.','在矿工往地下钻的所有孔洞里,为找石油而打的那些是最深的;有的深达两万五千英尺。可是,与为煤或别的矿藏挖的竖井不同,这些孔从来不是要把人送下地底的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l13',2,NULL,'They are only narrow borings, less than a foot across, and it is largely the hunt for oil that has pushed the art of deep drilling further than any other kind of mining. Once the geologists have decided where to drill, a tall steel tower, the derrick, is raised above the spot.','它们只是窄窄的钻孔,直径不到一英尺;正是这场找油的追逐,把深钻的技艺推得比任何别的采矿都远。地质学家一旦决定在哪里钻,一座高高的钢塔——井架——便被竖立在那地点之上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l13',3,NULL,'It has to stand high because it works like a giant block and tackle: from it, great lengths of pipe are lowered into the ground and later hauled out again. The pipe is rotated by a powerful engine at the top and is fitted at the bottom with a hard cutting bit that bites into the rock.','它必须立得高,因为它像一套巨大的滑轮组:一根根长长的钻管从它上面被放入地下,过后又被拽出来。钻管由顶端一台大功率发动机带动旋转,底部装着一枚硬硬的钻头,咬进岩石。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l13',4,NULL,'Because the crew must know exactly which layers the drill has reached, a sample is now and then taken with a special coring bit, which cuts a clean cylinder of stone, from which the strata that the drill has been passing through can be clearly read.','因为钻井队必须确切知道钻头钻到了哪些岩层,他们时不时用一枚特制的取芯钻头取一块样本;它切出一段干净的岩柱,从这段岩芯里,可以清楚地读出钻头一路穿过的地层。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l13',5,NULL,'Once the bit breaks into the oil, the oil tends to rush up to the surface on its own, for it is driven by the great pressure of water or gas beneath it. That pressure must be kept firmly under control, and it is controlled by means of the heavy mud which the crew circulate down the pipe. Nobody today wants the old, romantic gusher that throws oil high into the air, since such a fountain only wastes oil and gas. The engineers want the oil to stay down the hole until it can be led off, quietly and safely, in a manner they choose.','钻头一旦钻进油层,油往往会自己涌向地面,因为它下方的水或天然气以巨大的压力把它顶着。那压力必须被牢牢控制住;控制的办法,是让沉重的泥浆在钻管里循环流下。今天谁也不想要那种老式而浪漫的井喷——把油高高喷向空中——因为那样一柱冲天只会白白浪费油和气。工程师们希望油乖乖待在井里,直到能以他们所选定的方式,安安静静、稳稳当当地把它引出来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
