INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l15','labeled','labelled','标注(过去式);拼写差异,美语单 l') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
