INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l15','carry out','',NULL,'/ˈkæri aʊt/','The research is carried out in secret.','这项研究是秘密进行的。','They carried out the plan.','他们执行了这个计划。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l15','take out','',NULL,'/teɪk aʊt/','A firm can take out a patent.','公司可以申请专利。','He took out a loan.','他办了一笔贷款。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l15','as long as','',NULL,'/æz lɔːŋ æz/','As long as it stays secret, no one can share it.','只要它还保密,谁也无法分享。','You may stay as long as you like.','你想待多久都行。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l15','be likely to','',NULL,'/bi ˈlaɪkli tə/','Rivals are likely to be doing the same work.','对手很可能在做同样的工作。','It''s likely to rain.','很可能要下雨。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp1','choice','{"stem":"\"The research is ___ fundamental that hiding it brings no gain.\"(‘如此…以至于’,修饰形容词时用的那个词)","options":["so","very","too","such"],"answer_index":0,"stem_cn":"这项研究如此基础,以至于藏着它毫无好处。","explanation_cn":"‘如此…以至于’修饰形容词(fundamental)时用 so。✓ so fundamental that hiding it brings no gain. ✗ such(修饰名词)/ very / too:修饰形容词用 so … that。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp1','choice','{"stem":"\"It is ___ a broad study that secrecy is pointless.\"(‘如此一项…以至于’,后接 a + 名词短语时用的那个词)","options":["too","very","so","such"],"answer_index":3,"stem_cn":"这是一项如此宽泛的研究,保密毫无意义。","explanation_cn":"‘如此一项…以至于’后接 a + 名词短语时用 such。✓ such a broad study that secrecy is pointless. ✗ so(修饰形容词)/ very / too:接名词短语用 such … that。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp1','choice','{"stem":"\"Secrecy is carried to such an ___ that the subject cannot be named.\"(to such an … that:‘到…地步’,填名词)","options":["extreme","exterior","extremely","extra"],"answer_index":0,"stem_cn":"保密到了连课题都不能提的地步。","explanation_cn":"to such an extreme that:‘到…极端地步以至于’;填名词 extreme。✓ to such an extreme that the subject cannot be named. ✗ extremely(副词)/ extra / exterior:此处用名词 extreme。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp2','choice','{"stem":"\"Chance discoveries play a ___ larger part in chemistry than in physics.\"(比较级前的加强词,‘大得多’)","options":["very","most","far","so"],"answer_index":2,"stem_cn":"偶然发现在化学中的作用比在物理中大得多。","explanation_cn":"比较级 larger 前的加强词,‘大得多’用 far。✓ a far larger part than in physics. ✗ very(不修饰比较级)/ so / most:加强比较级用 far/much。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp2','choice','{"stem":"\"This process is ___ more secret than the last one.\"(比较级 more 前的加强词)","options":["much","very","most","more"],"answer_index":0,"stem_cn":"这道工序比上一道保密得多。","explanation_cn":"比较级 more 前的加强词,‘…得多’用 much。✓ much more secret than the last one. ✗ very / more / most:加强比较级用 much/far。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp2','choice','{"stem":"\"A lucky find matters ___ more here than careful planning.\"(比较级前的加强词)","options":["so","too","far","very"],"answer_index":2,"stem_cn":"在这里,一次幸运的发现远比周密计划更重要。","explanation_cn":"比较级 more 前的加强词,‘远比…’用 far。✓ matters far more here. ✗ very / so / too:加强比较级用 far/much。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp3','choice','{"stem":"\"Processes ___ on such research are kept secret.\"(现在分词作定语,主动‘依赖…的’)","options":["depended","depend","to depend","depending"],"answer_index":3,"stem_cn":"依赖这种研究的工序被保密。","explanation_cn":"现在分词作定语,表主动“依赖…的”。✓ Processes depending on such research. ✗ depended(被动/过去)/ depend / to depend:主动定语用 -ing。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp3','choice','{"stem":"\"Everyone ___ on the project is cut off from outsiders.\"(现在分词作定语,主动‘从事…的’)","options":["working","worked","to work","work"],"answer_index":0,"stem_cn":"参与这个项目的每个人都与外界隔绝。","explanation_cn":"现在分词作定语,表主动“从事…的”。✓ Everyone working on the project. ✗ worked / work / to work:主动定语用 -ing。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp3','choice','{"stem":"\"A book ___ out under a firm''s name may reveal its research.\"(过去分词作定语,‘被借出的’;take 的过去分词)","options":["to take","taking","taken","take"],"answer_index":2,"stem_cn":"以某公司名义借出的一本书可能泄露其研究。","explanation_cn":"过去分词作定语,表被动“被借出的”;take 的过去分词 taken。✓ a book taken out under a firm''s name. ✗ taking(主动)/ take / to take:被动定语用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp4','choice','{"stem":"\"A useful process can ___ patented before rivals copy it.\"(情态被动 can + ___ + 过去分词,填中间的词)","options":["being","is","been","be"],"answer_index":3,"stem_cn":"一道有用的工序可以在对手仿造前被申请专利。","explanation_cn":"情态词被动 can + be + 过去分词;中间那个词是 be。✓ can be patented before rivals copy it. ✗ is / been / being:can 后用原形 be + 过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp4','choice','{"stem":"\"The subject of the research ___ not even be mentioned.\"(‘甚至不能被提及’,填与 not 连用表‘不能’的情态词)","options":["is","does","can","has"],"answer_index":2,"stem_cn":"研究的课题甚至不能被提及。","explanation_cn":"‘甚至不能被提及’= cannot be mentioned;与 not 连用表‘不能’的情态词是 can。✓ cannot even be mentioned. ✗ is / has / does:表‘能/不能’用 can。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp4','choice','{"stem":"\"Such secrets ___ be kept until a patent is granted.\"(‘必须被保守’,填表‘必须’的情态词)","options":["must","does","has","is"],"answer_index":0,"stem_cn":"这类秘密必须一直保守到专利获批。","explanation_cn":"‘必须被保守’= must be kept;表‘必须’的情态词是 must。✓ must be kept until a patent is granted. ✗ is / has / does:表‘必须’用 must。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp5','choice','{"stem":"\"They hide the title ___ fear rivals should trace their work.\"(‘唯恐、生怕’= ___ fear,填 fear 前的介词)","options":["by","with","for","in"],"answer_index":2,"stem_cn":"他们隐去书名,唯恐对手追查到他们的工作。","explanation_cn":"‘唯恐、生怕’= for fear;fear 前的介词用 for。✓ for fear rivals should trace their work. ✗ in / by / with:此结构用 for fear。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp5','choice','{"stem":"\"They keep it secret for fear that agents ___ trace the research.\"(for fear that … ___ + 动词原形,‘唯恐会…’,填这个助动词)","options":["must","dare","need","should"],"answer_index":3,"stem_cn":"他们保密,唯恐特工会追查到那研究。","explanation_cn":"for fear that … should + 动词原形,‘唯恐会…’;填 should。✓ for fear that agents should trace the research. ✗ must / need / dare:此结构用 should。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp5','choice','{"stem":"\"Rivals are ___ to be undertaking similar research.\"(be ___ to do,‘很可能(做)’,填形容词)","options":["liking","alike","likely","like"],"answer_index":2,"stem_cn":"竞争对手很可能正在做类似的研究。","explanation_cn":"be likely to do,‘很可能(做)’;填形容词 likely。✓ Rivals are likely to be undertaking research. ✗ like / alike / liking:be … to do 用形容词 likely。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp6','choice','{"stem":"\"The state of keeping things hidden from others is ___.\"(“保密、秘密状态”用哪个词)","options":["honesty","secrecy","fame","openness"],"answer_index":1,"stem_cn":"把事情对别人隐瞒的状态。","explanation_cn":"把事情对别人隐瞒的状态是 secrecy(保密)。✓ the state of keeping things hidden is secrecy. ✗ openness 公开;✗ honesty 诚实;✗ fame 名声——都相反或不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp6','choice','{"stem":"\"A legal right protecting a new invention is a ___.\"(“专利”用哪个词)","options":["ticket","license","patent","receipt"],"answer_index":2,"stem_cn":"保护一项新发明的合法权利。","explanation_cn":"保护一项新发明的合法权利是 patent(专利)。✓ a legal right protecting an invention is a patent. ✗ license 执照;✗ receipt 收据;✗ ticket 票——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',5,'am4_l15_gp6','choice','{"stem":"\"To follow clues and find out something''s course is to ___ it.\"(“追踪、查出”用哪个词)","options":["ignore","hide","waste","trace"],"answer_index":3,"stem_cn":"顺着线索查出某事物的来龙去脉。","explanation_cn":"顺着线索查出来龙去脉是 trace(追踪)。✓ to follow clues and find out is to trace. ✗ hide 隐藏;✗ waste 浪费;✗ ignore 忽视——都相反或不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"secrecy 的意思是:","options":["诚实","公开","名声","保密,秘密状态"],"answer_index":3,"explanation_cn":"secrecy = 保密、秘密状态。✓ the heavy atmosphere of secrecy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"effectiveness 的意思是:","options":["弱点","效力,成效","距离","重量"],"answer_index":1,"explanation_cn":"effectiveness = 效力、成效。✓ weaken the effectiveness of research."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"inquiry 的意思是:","options":["调查,探究","假期","礼物","命令"],"answer_index":0,"explanation_cn":"inquiry = 调查、探究。✓ as long as an inquiry is treated as a secret."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"patent 的意思是:","options":["罚款","收据","专利","执照"],"answer_index":2,"explanation_cn":"patent = 专利。✓ a patent can be taken out."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"fundamental 的意思是:","options":["多余的","次要的","临时的","基础的,根本的"],"answer_index":3,"explanation_cn":"fundamental = 基础的、根本的。✓ so broad and so fundamental in nature."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',6,NULL,'choice','{"stem":"undertake 的意思是:","options":["放弃","忘记","从事,着手","拒绝"],"answer_index":2,"explanation_cn":"undertake = 从事、着手。✓ the work they are likely to be undertaking."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',7,NULL,'cloze','{"stem":"第 1 空","context":"Two things weaken the ___1___ of research inside a firm. As long as an inquiry stays secret, it cuts workers off from others. Some studies are ___2___ fundamental that hiding them brings no gain. Many processes are kept secret until a patent can ___3___ taken out, ___4___ fear rivals trace the work.","blank_no":1,"options":["effectiveness","secrecy","patent","agent"],"answer_index":0,"explanation_cn":"effectiveness = 效力、成效。✓ weaken the effectiveness of research inside a firm."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',7,NULL,'cloze','{"stem":"第 2 空","context":"Two things weaken the ___1___ of research inside a firm. As long as an inquiry stays secret, it cuts workers off from others. Some studies are ___2___ fundamental that hiding them brings no gain. Many processes are kept secret until a patent can ___3___ taken out, ___4___ fear rivals trace the work.","blank_no":2,"options":["so","such","very","too"],"answer_index":0,"explanation_cn":"‘如此…以至于’修饰形容词用 so。✓ so fundamental that hiding them brings no gain."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',7,NULL,'cloze','{"stem":"第 3 空","context":"Two things weaken the ___1___ of research inside a firm. As long as an inquiry stays secret, it cuts workers off from others. Some studies are ___2___ fundamental that hiding them brings no gain. Many processes are kept secret until a patent can ___3___ taken out, ___4___ fear rivals trace the work.","blank_no":3,"options":["be","is","been","being"],"answer_index":0,"explanation_cn":"情态词被动 can + be + 过去分词;中间用 be。✓ a patent can be taken out."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',7,NULL,'cloze','{"stem":"第 4 空","context":"Two things weaken the ___1___ of research inside a firm. As long as an inquiry stays secret, it cuts workers off from others. Some studies are ___2___ fundamental that hiding them brings no gain. Many processes are kept secret until a patent can ___3___ taken out, ___4___ fear rivals trace the work.","blank_no":4,"options":["for","in","by","with"],"answer_index":0,"explanation_cn":"‘唯恐、生怕’= for fear;用 for。✓ for fear rivals trace the work."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',8,NULL,'choice','{"stem":"Why is secrecy especially important in the chemical industries?","options":["Because chemicals are dangerous","Because chemists work alone","Because the law requires it","Because chance discoveries play a far larger part there than in other industries"],"answer_index":3,"explanation_cn":"录音说保密在化学工业尤其重要,因为偶然发现在那里的作用远比别的行业大得多。✓ chance discoveries far larger part."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',8,NULL,'choice','{"stem":"What are the two things that weaken research inside a firm?","options":["The atmosphere of secrecy and the lack of freedom for the researcher","Poor pay and bad tools","Weather and distance","High costs and long hours"],"answer_index":0,"explanation_cn":"录音说削弱公司内部科研的两样东西:保密的气氛,以及研究者缺乏自由。✓ secrecy + lack of freedom."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',8,NULL,'choice','{"stem":"Why do some firms avoid borrowing books from libraries?","options":["Because libraries are closed","For fear rivals could trace the research they are undertaking","Because they dislike reading","Because books are too expensive"],"answer_index":1,"explanation_cn":"录音说有些公司不愿在图书馆留下名字,唯恐对手借此查出它们正在做的研究。✓ for fear rivals trace the research."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',9,NULL,'choice','{"stem":"你想说\"这项研究如此基础,以至于藏着它毫无好处\"(so…that):","options":["The research so fundamental is that hiding it brings no gain.","The research is so fundamental that hiding it brings no gain.","The research is such fundamental that hiding it brings no gain.","The research is so fundamental as hiding it brings no gain."],"answer_index":1,"explanation_cn":"so + 形容词 + that:修饰形容词 fundamental 用 so 不用 such;结果连词用 that 不用 as;语序为 is so fundamental。✓ so fundamental that … 场合:说“如此…以至于…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',9,NULL,'choice','{"stem":"你想说\"研究的课题甚至不能被提及\"(情态词被动):","options":["The subject of the research cannot even be mentioned.","The subject of the research cannot even be mention.","The subject of the research cannot even mentioned.","The subject of the research can not even be mentioning."],"answer_index":0,"explanation_cn":"情态词被动 cannot + be + 过去分词 mentioned;mention 须用过去分词 mentioned、不能少 be、不用 -ing mentioning。✓ cannot even be mentioned. 场合:说“甚至不能被…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',9,NULL,'choice','{"stem":"你想说\"竞争对手很可能正在做类似的研究\"(be likely to):","options":["Rivals are like to be undertaking similar research.","Rivals are likely be undertaking similar research.","Rivals are likely to being undertaking similar research.","Rivals are likely to be undertaking similar research."],"answer_index":3,"explanation_cn":"be likely to do:likely 后接不定式 to be;不能少 to、不用 to being、likely 不写成 like。✓ are likely to be undertaking. 场合:说“很可能正在…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"secrecy 的意思是:","options":["诚实","保密,秘密状态","名声","公开"],"answer_index":1,"explanation_cn":"secrecy = 保密、秘密状态。✓ the atmosphere of secrecy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"patent 的意思是:","options":["专利","收据","罚款","执照"],"answer_index":0,"explanation_cn":"patent = 专利。✓ a patent can be taken out."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"\"The research is ___ fundamental that hiding it brings no gain.\"(如此…以至于,后接形容词)","options":["such","so","very","too"],"answer_index":1,"stem_cn":"这项研究如此基础,以至于藏着它毫无好处。","explanation_cn":"‘如此…以至于’修饰形容词用 so。✓ so fundamental that hiding it brings no gain. ✗ such / very / too。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"\"A process can ___ patented before rivals copy it.\"(情态被动 can + ___ + 过去分词)","options":["being","been","be","is"],"answer_index":2,"stem_cn":"一道工序可以在对手仿造前被申请专利。","explanation_cn":"情态词被动 can + be + 过去分词;中间用 be。✓ a process can be patented. ✗ is / been / being。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"\"carry out\" 的意思是:","options":["抱怨","推迟","拿出去","进行、执行"],"answer_index":3,"explanation_cn":"carry out = 进行、执行。✓ the research is carried out in secret."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"\"be likely to\" 的意思是:","options":["很可能(做)","拒绝做","喜欢做","假装做"],"answer_index":0,"explanation_cn":"be likely to = 很可能(做)。✓ rivals are likely to be doing the same work."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"Why is secrecy especially important in the chemical industries?","options":["The chemicals are cheap","The workers are careless","Chance discoveries play a far larger part there than elsewhere","The government owns them"],"answer_index":2,"passage":"Two things, more than any others, weaken the effectiveness of scientific research when it is carried on inside a private company. The first is the heavy atmosphere of secrecy that hangs over the work; the second is the narrow freedom left to the individual researcher. As long as an inquiry is treated as a secret, it cuts off everyone working on it from any real exchange with fellow scientists — those in other countries, those in the universities, and often enough those in other departments of the very same firm. How much secrecy a company keeps varies a great deal. A few of the largest firms carry out research so broad and so fundamental in nature that it is a positive advantage to them not to hide it at all. Yet a great many useful processes depending on that research are pursued behind complete secrecy right up to the moment when a patent can be taken out, and still more are never patented but simply kept as private secrets. This is especially true of the chemical industries, where a lucky, chance discovery plays a far larger part than it does in the physical or mechanical trades. Now and then the secrecy is carried to such an extreme that the very subject of the research cannot be named out loud. Some firms, for instance, find it surprisingly hard to borrow technical books from a public library, because they are unwilling to let their names be recorded as having taken out this or that volume — for fear that the agents of rival companies should manage to trace the sort of work they are likely to be undertaking.","explanation_cn":"课文说化学工业里保密尤其重要,因为一次偶然发现的作用比别处大得多。✓ chance discoveries far larger part."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"What does secrecy do to the individual researcher?","options":["It doubles their pay","It cuts them off from effective contact with fellow scientists","It gives them more freedom","It makes their work public"],"answer_index":1,"passage":"Two things, more than any others, weaken the effectiveness of scientific research when it is carried on inside a private company. The first is the heavy atmosphere of secrecy that hangs over the work; the second is the narrow freedom left to the individual researcher. As long as an inquiry is treated as a secret, it cuts off everyone working on it from any real exchange with fellow scientists — those in other countries, those in the universities, and often enough those in other departments of the very same firm. How much secrecy a company keeps varies a great deal. A few of the largest firms carry out research so broad and so fundamental in nature that it is a positive advantage to them not to hide it at all. Yet a great many useful processes depending on that research are pursued behind complete secrecy right up to the moment when a patent can be taken out, and still more are never patented but simply kept as private secrets. This is especially true of the chemical industries, where a lucky, chance discovery plays a far larger part than it does in the physical or mechanical trades. Now and then the secrecy is carried to such an extreme that the very subject of the research cannot be named out loud. Some firms, for instance, find it surprisingly hard to borrow technical books from a public library, because they are unwilling to let their names be recorded as having taken out this or that volume — for fear that the agents of rival companies should manage to trace the sort of work they are likely to be undertaking.","explanation_cn":"课文说只要研究保密,就把研究者同别国、大学、乃至同公司别部门的同行的真正交流切断了。✓ cuts off from fellow scientists."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"What are the two things that weaken industrial research?","options":["The atmosphere of secrecy and the lack of freedom","Money and time","Heat and noise","Distance and language"],"answer_index":0,"audio":"Two things, more than any others, weaken the effectiveness of scientific research when it is carried on inside a private company. The first is the heavy atmosphere of secrecy that hangs over the work; the second is the narrow freedom left to the individual researcher. As long as an inquiry is treated as a secret, it cuts off everyone working on it from any real exchange with fellow scientists — those in other countries, those in the universities, and often enough those in other departments of the very same firm. How much secrecy a company keeps varies a great deal. A few of the largest firms carry out research so broad and so fundamental in nature that it is a positive advantage to them not to hide it at all. Yet a great many useful processes depending on that research are pursued behind complete secrecy right up to the moment when a patent can be taken out, and still more are never patented but simply kept as private secrets. This is especially true of the chemical industries, where a lucky, chance discovery plays a far larger part than it does in the physical or mechanical trades. Now and then the secrecy is carried to such an extreme that the very subject of the research cannot be named out loud. Some firms, for instance, find it surprisingly hard to borrow technical books from a public library, because they are unwilling to let their names be recorded as having taken out this or that volume — for fear that the agents of rival companies should manage to trace the sort of work they are likely to be undertaking.","explanation_cn":"课文说削弱公司内部科研的两样东西:保密的气氛与研究者的缺乏自由。✓ secrecy + lack of freedom."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l15',10,NULL,'choice','{"stem":"Why won''t some firms let their names be entered at a library?","options":["Because books cost too much","Because they lost their cards","For fear rivals could trace the research they are undertaking","Because they never read"],"answer_index":2,"audio":"Two things, more than any others, weaken the effectiveness of scientific research when it is carried on inside a private company. The first is the heavy atmosphere of secrecy that hangs over the work; the second is the narrow freedom left to the individual researcher. As long as an inquiry is treated as a secret, it cuts off everyone working on it from any real exchange with fellow scientists — those in other countries, those in the universities, and often enough those in other departments of the very same firm. How much secrecy a company keeps varies a great deal. A few of the largest firms carry out research so broad and so fundamental in nature that it is a positive advantage to them not to hide it at all. Yet a great many useful processes depending on that research are pursued behind complete secrecy right up to the moment when a patent can be taken out, and still more are never patented but simply kept as private secrets. This is especially true of the chemical industries, where a lucky, chance discovery plays a far larger part than it does in the physical or mechanical trades. Now and then the secrecy is carried to such an extreme that the very subject of the research cannot be named out loud. Some firms, for instance, find it surprisingly hard to borrow technical books from a public library, because they are unwilling to let their names be recorded as having taken out this or that volume — for fear that the agents of rival companies should manage to trace the sort of work they are likely to be undertaking.","explanation_cn":"课文说有些公司不愿在图书馆留名,唯恐对手借此查出它们正在从事的研究。✓ for fear rivals trace the research."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l16',4,3,16,'The Modern City','现代城市','现在完成被动(have/has been done:cities have been raised / it has not been planned)、so that … may …(目的)+ as … as possible、过去分词作定语(life imposed by the factory / streets choked with fumes)、where 引导的定语从句(towers where people are packed)、While 引导的让步 + that 宾语从句(NCE4 无 KS 页,考点由课文结构自取;IP:源为阿列克西·卡雷尔《人之奥秘》论著,已用 100% 原创行文复述‘现代城市为逐利而建、不顾居民身心’的批判,无人物、无逐句改写;题材=城市与工业化反思·无害;美语化 gasoline/truck/apartment;第四册第16课)','当我们组织工业生活时,几乎完全忘了工厂对在其中劳作的男男女女的身体与心灵所起的作用。现代工业建立在一个念头之上:以尽可能低的成本换取尽可能大的产量,好让一家公司或一个人尽量多赚钱。它一路膨胀,却全然不顾照看机器的那些人究竟是怎样的存在,也丝毫不曾考虑工厂强加的那种人为生活,会给这些工人及其后代带来什么。我们的大城市几乎毫不顾及我们便拔地而起。一座摩天大楼的高度与尺寸,完全由这样的心思决定:从每一平方英尺土地上榨出最大的租金,并给租户提供能吸引他们的那种办公室与公寓。就这样,一座座庞大而狰狞的高塔被竖了起来,塔里塞进了太多太多的人。文明人似乎很喜欢这样一种生活方式。他们一边享受着房间里的舒适与廉价的奢华,一边却从没察觉,自己已被剥夺了生活真正的必需品。归根结底,现代城市不过是一堆巨大的楼房和阴暗狭窄的街道,被无数引擎的毒气所窒塞,被汽车和公交没完没了的轰鸣所震动,从早到晚被躁动的人群挤满。显然,它并不是为住在其中的人的福祉而规划的。','{"q":"Listen and answer — What is the author''s main argument about the modern city?","options":["It is built for profit, with no regard for the good of its inhabitants","It is the healthiest place to live","It was carefully planned around nature","It has too few tall buildings"],"answer_index":0}'::jsonb,'{"title":"现在完成被动 / so that 目的 / 过去分词作定语 / where 定语从句 / While 让步","intro":"①现在完成被动 have/has + been + 过去分词:cities have been raised;it has not been planned。②so that … may …(目的);as … as possible。③过去分词作定语:the life imposed by the factory;streets choked with fumes。④where 引导定语从句(先行词是地点):towers where people are packed。⑤While(虽然)引导让步;realize that …(宾语从句)。","table":{"headers":["用法","结构","例子"],"rows":[["现在完成被动","have/has been + 过去分词","the cities have been raised"],["so that 目的","so that … may …","so that a person may make money"],["过去分词作定语","名词 + 过去分词","the life imposed by the factory"],["where 定语从句","地点 + where + 从句","towers where people are packed"],["While 让步","While + 从句, 主句","While they enjoy it, they miss much"]]},"specialRules":[{"rule":"现在完成被动=have/has + been + 过去分词,主语单数用 has been,复数用 have been。","mark":"have/has been done"},{"rule":"where 引导定语从句时先行词是表地点的名词(place, city, tower…),在从句中作状语。","mark":"地点 + where + 从句"},{"rule":"美式拼写/用词:gasoline(汽油,英式 petrol)、truck(卡车,英式 lorry)、apartment(公寓,英式 flat)。本课已按美语写。","mark":"gasoline / truck / apartment"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l16',1,NULL,'When we organize our industrial life, we almost entirely forget the effect that the factory has on the body and mind of the men and women who work in it. Modern industry rests on a single idea: the greatest possible output at the lowest possible cost, so that a company or a person may make as much money as it can.','当我们组织工业生活时,几乎完全忘了工厂对在其中劳作的男男女女的身体与心灵所起的作用。现代工业建立在一个念头之上:以尽可能低的成本换取尽可能大的产量,好让一家公司或一个人尽量多赚钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l16',2,NULL,'It has grown without any real thought for the human beings who tend the machines, and without the slightest consideration for what the artificial life imposed by the factory does to those workers and to their descendants.','它一路膨胀,却全然不顾照看机器的那些人究竟是怎样的存在,也丝毫不曾考虑工厂强加的那种人为生活,会给这些工人及其后代带来什么。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l16',3,NULL,'Our great cities have been raised with almost no regard for us. The height and dimensions of a skyscraper are decided entirely by the wish to squeeze the maximum rent out of every square foot of ground, and to offer tenants the kind of offices and apartments that will attract them.','我们的大城市几乎毫不顾及我们便拔地而起。一座摩天大楼的高度与尺寸,完全由这样的心思决定:从每一平方英尺土地上榨出最大的租金,并给租户提供能吸引他们的那种办公室与公寓。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l16',4,NULL,'In this way enormous, monstrous towers have been thrown up, towers where far too many people are packed together. Civilized men seem to enjoy such a way of living. While they take pleasure in the comfort and the cheap luxury of their rooms, they never notice that they have been deprived of the true necessities of life.','就这样,一座座庞大而狰狞的高塔被竖了起来,塔里塞进了太多太多的人。文明人似乎很喜欢这样一种生活方式。他们一边享受着房间里的舒适与廉价的奢华,一边却从没察觉,自己已被剥夺了生活真正的必需品。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l16',5,NULL,'The modern city, in the end, is little more than a mass of huge buildings and dark, narrow streets, choked with the toxic fumes of countless engines, shaken by the endless roar of cars and buses, and thronged from morning to night by restless crowds. Plainly, it has not been planned for the good of the people who must live in it.','归根结底,现代城市不过是一堆巨大的楼房和阴暗狭窄的街道,被无数引擎的毒气所窒塞,被汽车和公交没完没了的轰鸣所震动,从早到晚被躁动的人群挤满。显然,它并不是为住在其中的人的福祉而规划的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
