INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l16','little more than','',NULL,'/ˈlɪtl mɔːr ðæn/','The city is little more than a mass of buildings.','这座城市不过是一堆楼房而已。','It was little more than a shed.','那不过是个棚子罢了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l16','take pleasure in','',NULL,'/teɪk ˈpleʒər ɪn/','They take pleasure in cheap luxury.','他们乐于享受廉价的奢华。','She takes pleasure in helping others.','她乐于助人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l16','with no regard for','',NULL,'/wɪð noʊ rɪˈɡɑːrd fɔːr/','The cities were built with no regard for us.','这些城市的建造毫不顾及我们。','He drove with no regard for safety.','他开车全然不顾安全。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l16','pack together','',NULL,'/pæk təˈɡeðər/','Too many people are packed together in the tower.','塔里塞进了太多人。','The books were packed together on one shelf.','书都挤在一个书架上。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp1','choice','{"stem":"\"The great cities ___ been raised with no regard for us.\"(现在完成被动 ___ + been + 过去分词,填第一个助动词)","options":["did","has","are","have"],"answer_index":3,"stem_cn":"那些大城市的建造根本不顾我们。","explanation_cn":"现在完成被动 have/has + been + 过去分词;主语 cities 复数,第一个助动词用 have。✓ The great cities have been raised. ✗ has(单数)/ are(缺 been)/ did:复数用 have been done。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp1','choice','{"stem":"\"The city has not ___ planned for its people.\"(现在完成被动 has not + ___ + 过去分词,填中间的词)","options":["been","be","being","was"],"answer_index":0,"stem_cn":"这座城市的规划并不为它的居民着想。","explanation_cn":"现在完成被动 has not + been + 过去分词;中间那个词是 been。✓ has not been planned. ✗ be / being / was:has 后用 been + 过去分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp1','choice','{"stem":"\"Workers have been ___ of the necessities of life.\"(现在完成被动 have been + 过去分词;deprive 的过去分词)","options":["deprive","to deprive","deprived","depriving"],"answer_index":2,"stem_cn":"工人被剥夺了生活的必需品。","explanation_cn":"现在完成被动 have been + 过去分词;deprive 的过去分词 deprived。✓ have been deprived of the necessities. ✗ depriving(主动)/ deprive / to deprive:被动用过去分词 deprived。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp2','choice','{"stem":"\"Factories cut costs so ___ owners may earn more.\"(‘以便、为了’的目的连词 so ___,填第二个词)","options":["which","for","as","that"],"answer_index":3,"stem_cn":"工厂压低成本,以便老板多赚。","explanation_cn":"‘以便、为了’的目的连词 so that;第二个词是 that。✓ cut costs so that owners may earn more. ✗ as / for / which:目的用 so that。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp2','choice','{"stem":"\"They aim at the ___ output at the lowest cost.\"(‘最大的’,填形容词)","options":["minimum","least","maximum","small"],"answer_index":2,"stem_cn":"他们追求成本最低下的最大产量。","explanation_cn":"‘最大的’用 maximum。✓ the maximum output at the lowest cost. ✗ minimum 最小;✗ least 最少;✗ small 小——都相反或不对。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp2','choice','{"stem":"\"Each person wants to earn as much money as ___.\"(as much … as ___:‘尽可能多’,填这个词)","options":["much","more","can","possible"],"answer_index":3,"stem_cn":"每个人都想尽可能多赚钱。","explanation_cn":"as much … as possible:‘尽可能多’;固定用 possible。✓ earn as much money as possible. ✗ can / much / more:此结构末尾用 possible。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp3','choice','{"stem":"\"The artificial life ___ by the factory harms the workers.\"(过去分词作定语,‘被强加的’;impose 的过去分词)","options":["imposed","imposing","to impose","impose"],"answer_index":0,"stem_cn":"工厂强加的人为生活损害着工人。","explanation_cn":"过去分词作定语,表被动‘被强加的’;impose 的过去分词 imposed。✓ the artificial life imposed by the factory. ✗ imposing(主动)/ impose / to impose:被动定语用过去分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp3','choice','{"stem":"\"Streets ___ with toxic fumes fill the modern city.\"(过去分词作定语,‘被…堵塞的’;choke 的过去分词)","options":["choke","to choke","choking","choked"],"answer_index":3,"stem_cn":"被毒气堵塞的街道充斥着现代城市。","explanation_cn":"过去分词作定语,表被动‘被…堵塞的’;choke 的过去分词 choked。✓ streets choked with toxic fumes. ✗ choking(主动)/ choke / to choke:被动定语用过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp3','choice','{"stem":"\"The effects ___ on their descendants are ignored.\"(过去分词作定语,‘施加于…的’;produce 的过去分词)","options":["to produce","producing","produced","produce"],"answer_index":2,"stem_cn":"对其后代造成的影响被忽视了。","explanation_cn":"过去分词作定语,表被动‘施加于…的’;produce 的过去分词 produced。✓ the effects produced on their descendants. ✗ producing(主动)/ produce / to produce:被动定语用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp4','choice','{"stem":"\"They build towers ___ too many people are packed together.\"(定语从句,指地点,填关系副词)","options":["that","where","which","when"],"answer_index":1,"stem_cn":"他们盖起挤满太多人的高楼。","explanation_cn":"定语从句先行词是地点(towers),关系副词用 where。✓ towers where too many people are packed. ✗ which / that(作关系代词需在从句中充当成分)/ when(指时间):指地点用 where。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp4','choice','{"stem":"\"The factory is a place ___ workers lose their health.\"(定语从句,指地点,填关系副词)","options":["where","which","who","what"],"answer_index":0,"stem_cn":"工厂是工人失去健康的地方。","explanation_cn":"定语从句先行词是地点(a place),关系副词用 where。✓ a place where workers lose their health. ✗ which / who / what:指地点用 where。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp4','choice','{"stem":"\"This is a city ___ nobody thinks of the inhabitants.\"(定语从句,指地点,填关系副词)","options":["that","where","which","whom"],"answer_index":1,"stem_cn":"这是一座没人想着居民的城市。","explanation_cn":"定语从句先行词是地点(a city),关系副词用 where。✓ a city where nobody thinks of the inhabitants. ✗ which / that / whom:指地点用 where。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp5','choice','{"stem":"\"___ they enjoy the luxury, they miss the real necessities.\"(‘虽然、尽管’,填连词)","options":["While","Because","Since","Unless"],"answer_index":0,"stem_cn":"虽然他们享受着奢华,却错失了真正的必需品。","explanation_cn":"‘虽然、尽管’引导让步,用 While。✓ While they enjoy the luxury, they miss the necessities. ✗ Because(因为)/ Unless(除非)/ Since:表‘虽然’用 While。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp5','choice','{"stem":"\"They do not realize ___ they have been deprived of much.\"(宾语从句,‘…这件事’,填连词)","options":["what","that","whether","which"],"answer_index":1,"stem_cn":"他们没意识到自己已被剥夺了许多。","explanation_cn":"从句作 realize 的对象,‘…这件事’,用 that。✓ do not realize that they have been deprived. ✗ what / which / whether:此处用 that。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp5','choice','{"stem":"\"___ the city looks grand, it is not built for people.\"(‘尽管’,填让步连词)","options":["Unless","Because","Once","While"],"answer_index":3,"stem_cn":"尽管这城市看着宏伟,却不是为人而建。","explanation_cn":"‘尽管’引导让步,用 While。✓ While the city looks grand, it is not built for people. ✗ Because / Once / Unless:表‘尽管’用 While。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp6','choice','{"stem":"\"A very tall city building of many floors is a ___.\"(“摩天大楼”用哪个词)","options":["tent","skyscraper","cottage","barn"],"answer_index":1,"stem_cn":"一座许多层的高高的城市大楼。","explanation_cn":"一座许多层的高高的城市大楼是 skyscraper(摩天大楼)。✓ a very tall building is a skyscraper. ✗ cottage 小屋;✗ barn 谷仓;✗ tent 帐篷——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp6','choice','{"stem":"\"A person who rents and lives in a place is a ___.\"(“租户、房客”用哪个词)","options":["tenant","guest","owner","judge"],"answer_index":0,"stem_cn":"租住某处的人。","explanation_cn":"租住某处的人是 tenant(租户)。✓ a person who rents a place is a tenant. ✗ owner 业主;✗ guest 客人;✗ judge 法官——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',5,'am4_l16_gp6','choice','{"stem":"\"Poisonous and harmful to living things means ___.\"(“有毒的”用哪个词)","options":["fresh","pure","sweet","toxic"],"answer_index":3,"stem_cn":"对生物有毒有害的。","explanation_cn":"对生物有毒有害的是 toxic(有毒的)。✓ poisonous and harmful means toxic. ✗ pure 纯净;✗ sweet 甜;✗ fresh 新鲜——都相反或不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"maximum 的意思是:","options":["临时的","最大的,最大限度的","平均的","最小的"],"answer_index":1,"explanation_cn":"maximum = 最大的、最大限度的。✓ the maximum rent out of every square foot."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"artificial 的意思是:","options":["天然的","古老的","免费的","人为的,人造的"],"answer_index":3,"explanation_cn":"artificial = 人为的、人造的。✓ the artificial life imposed by the factory."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"skyscraper 的意思是:","options":["摩天大楼","农舍","山洞","隧道"],"answer_index":0,"explanation_cn":"skyscraper = 摩天大楼。✓ the dimensions of a skyscraper."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"deprive 的意思是:","options":["储存","给予","购买","剥夺,使丧失"],"answer_index":3,"explanation_cn":"deprive = 剥夺、使丧失。✓ they have been deprived of the necessities."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"monstrous 的意思是:","options":["明亮的","巨大的,骇人的","微小的","温柔的"],"answer_index":1,"explanation_cn":"monstrous = 巨大的、狰狞可怕的。✓ enormous, monstrous towers."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',6,NULL,'choice','{"stem":"consideration 的意思是:","options":["命令","忽视","考虑,体谅","惩罚"],"answer_index":2,"explanation_cn":"consideration = 考虑、体谅。✓ without the slightest consideration."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',7,NULL,'cloze','{"stem":"第 1 空","context":"Modern industry cares only for the ___1___ output at the lowest cost. Cities ___2___ been raised with no regard for us. The artificial life ___3___ by the factory harms the workers. ___4___ people enjoy the luxury, they miss the real necessities.","blank_no":1,"options":["maximum","minimum","least","small"],"answer_index":0,"explanation_cn":"maximum = 最大的。✓ the maximum output at the lowest cost."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',7,NULL,'cloze','{"stem":"第 2 空","context":"Modern industry cares only for the ___1___ output at the lowest cost. Cities ___2___ been raised with no regard for us. The artificial life ___3___ by the factory harms the workers. ___4___ people enjoy the luxury, they miss the real necessities.","blank_no":2,"options":["have","has","are","did"],"answer_index":0,"explanation_cn":"现在完成被动;cities 复数用 have been + 过去分词。✓ Cities have been raised with no regard for us."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',7,NULL,'cloze','{"stem":"第 3 空","context":"Modern industry cares only for the ___1___ output at the lowest cost. Cities ___2___ been raised with no regard for us. The artificial life ___3___ by the factory harms the workers. ___4___ people enjoy the luxury, they miss the real necessities.","blank_no":3,"options":["imposed","imposing","impose","to impose"],"answer_index":0,"explanation_cn":"过去分词作定语,‘被强加的’。✓ the artificial life imposed by the factory."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',7,NULL,'cloze','{"stem":"第 4 空","context":"Modern industry cares only for the ___1___ output at the lowest cost. Cities ___2___ been raised with no regard for us. The artificial life ___3___ by the factory harms the workers. ___4___ people enjoy the luxury, they miss the real necessities.","blank_no":4,"options":["While","Because","Unless","Since"],"answer_index":0,"explanation_cn":"‘虽然、尽管’引导让步,用 While。✓ While people enjoy the luxury, they miss the necessities."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',8,NULL,'choice','{"stem":"What is the speaker''s main argument about the modern city?","options":["It is built for maximum profit, not for the good of the people who live in it","It is the healthiest place to live","It was planned around nature","It has too few buildings"],"answer_index":0,"explanation_cn":"录音说现代城市与工业是为最大利润而建,而不为住在其中的人的福祉。✓ built for profit, not for people."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',8,NULL,'choice','{"stem":"What decides the shape and height of a skyscraper?","options":["The beauty of the skyline","The health of the city","The wish to squeeze the maximum rent from every square foot","The comfort of the workers"],"answer_index":2,"explanation_cn":"录音说摩天楼的高度尺寸,完全由从每平方英尺榨出最大租金的心思决定。✓ maximum rent per square foot."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',8,NULL,'choice','{"stem":"What do civilized people fail to notice about their comfortable rooms?","options":["That the rooms are too large","That nature is nearby","That the rent is too low","That they have been deprived of the true necessities of life"],"answer_index":3,"explanation_cn":"录音说文明人享受舒适与廉价奢华,却没察觉自己已被剥夺了真正的生活必需品。✓ deprived of true necessities."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',9,NULL,'choice','{"stem":"你想说\"那些大城市的建造根本不顾我们\"(现在完成被动):","options":["The great cities have been raised with no regard for us.","The great cities have raised with no regard for us.","The great cities has been raised with no regard for us.","The great cities have been raise with no regard for us."],"answer_index":0,"explanation_cn":"现在完成被动 have + been + 过去分词 raised;复数用 have(不用 has)、不能少 been、raise 须用过去分词 raised。✓ have been raised. 场合:说“…已被(建/做)…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',9,NULL,'choice','{"stem":"你想说\"他们盖起挤满太多人的高楼\"(where 引导、指地点的从句):","options":["They build towers where too many people are packing together.","They build towers where too many people are packed together.","They build towers where too many people is packed together.","They build towers which too many people are packed together."],"answer_index":1,"explanation_cn":"where 引导、指地点(towers)的从句;不用 which(它需在从句里充当成分)、pack 用被动 are packed(不用 packing)、随复数用 are(不用 is)。✓ towers where … are packed. 场合:说“…的地方”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',9,NULL,'choice','{"stem":"你想说\"虽然他们享受着奢华,却错失了真正的必需品\"(While 让步):","options":["While they enjoying the luxury, they miss the real necessities.","While they enjoy the luxury, they misses the real necessities.","While they enjoy the luxury, but they miss the real necessities.","While they enjoy the luxury, they miss the real necessities."],"answer_index":3,"explanation_cn":"While‘虽然’引导让步,后面主句不再加 but;enjoy 用原形(不用 enjoying)、miss 随复数用原形(不用 misses)。✓ While they enjoy …, they miss … 场合:说“虽然…,却…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"maximum 的意思是:","options":["最小的","临时的","最大的,最大限度的","平均的"],"answer_index":2,"explanation_cn":"maximum = 最大的、最大限度的。✓ the maximum rent per square foot."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"deprive 的意思是:","options":["剥夺,使丧失","购买","给予","储存"],"answer_index":0,"explanation_cn":"deprive = 剥夺、使丧失。✓ deprived of the necessities of life."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"\"The great cities ___ been raised with no regard for us.\"(现在完成被动)","options":["did","are","has","have"],"answer_index":3,"stem_cn":"那些大城市的建造根本不顾我们。","explanation_cn":"现在完成被动;cities 复数用 have been + 过去分词。✓ The great cities have been raised. ✗ has / are / did。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"\"They build towers ___ too many people are packed together.\"(定语从句,指地点)","options":["where","which","when","that"],"answer_index":0,"stem_cn":"他们盖起挤满太多人的高楼。","explanation_cn":"定语从句先行词是地点(towers),关系副词用 where。✓ towers where too many people are packed. ✗ which / that / when。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"\"little more than\" 的意思是:","options":["一点也不","越来越多","只不过是、几乎就是","远远超过"],"answer_index":2,"explanation_cn":"little more than = 只不过是、几乎就是。✓ the city is little more than a mass of buildings."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"\"take pleasure in\" 的意思是:","options":["忘记","以…为乐、乐于","讨厌","害怕"],"answer_index":1,"explanation_cn":"take pleasure in = 以…为乐、乐于。✓ take pleasure in cheap luxury."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"According to the passage, what is modern industry based on?","options":["The beauty of the city","The health of its workers","The welfare of descendants","The greatest output at the lowest cost, so as to make the most money"],"answer_index":3,"passage":"When we organize our industrial life, we almost entirely forget the effect that the factory has on the body and mind of the men and women who work in it. Modern industry rests on a single idea: the greatest possible output at the lowest possible cost, so that a company or a person may make as much money as it can. It has grown without any real thought for the human beings who tend the machines, and without the slightest consideration for what the artificial life imposed by the factory does to those workers and to their descendants. Our great cities have been raised with almost no regard for us. The height and dimensions of a skyscraper are decided entirely by the wish to squeeze the maximum rent out of every square foot of ground, and to offer tenants the kind of offices and apartments that will attract them. In this way enormous, monstrous towers have been thrown up, towers where far too many people are packed together. Civilized men seem to enjoy such a way of living. While they take pleasure in the comfort and the cheap luxury of their rooms, they never notice that they have been deprived of the true necessities of life. The modern city, in the end, is little more than a mass of huge buildings and dark, narrow streets, choked with the toxic fumes of countless engines, shaken by the endless roar of cars and buses, and thronged from morning to night by restless crowds. Plainly, it has not been planned for the good of the people who must live in it.","explanation_cn":"课文说现代工业只建立在一个念头上:成本最低、产量最大,好尽量多赚钱。✓ greatest output, lowest cost, most money."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"What has the modern city been built with no regard for?","options":["The rent per square foot","The good of the people who must live in it","The comfort of tenants","The profit of the owners"],"answer_index":1,"passage":"When we organize our industrial life, we almost entirely forget the effect that the factory has on the body and mind of the men and women who work in it. Modern industry rests on a single idea: the greatest possible output at the lowest possible cost, so that a company or a person may make as much money as it can. It has grown without any real thought for the human beings who tend the machines, and without the slightest consideration for what the artificial life imposed by the factory does to those workers and to their descendants. Our great cities have been raised with almost no regard for us. The height and dimensions of a skyscraper are decided entirely by the wish to squeeze the maximum rent out of every square foot of ground, and to offer tenants the kind of offices and apartments that will attract them. In this way enormous, monstrous towers have been thrown up, towers where far too many people are packed together. Civilized men seem to enjoy such a way of living. While they take pleasure in the comfort and the cheap luxury of their rooms, they never notice that they have been deprived of the true necessities of life. The modern city, in the end, is little more than a mass of huge buildings and dark, narrow streets, choked with the toxic fumes of countless engines, shaken by the endless roar of cars and buses, and thronged from morning to night by restless crowds. Plainly, it has not been planned for the good of the people who must live in it.","explanation_cn":"课文说现代城市并不是为住在其中的人的福祉而规划的。✓ not for the good of the inhabitants."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"According to the speaker, for whose good has the modern city NOT been planned?","options":["The factory owners","The city planners","The tenants","The inhabitants who live in it"],"answer_index":3,"audio":"When we organize our industrial life, we almost entirely forget the effect that the factory has on the body and mind of the men and women who work in it. Modern industry rests on a single idea: the greatest possible output at the lowest possible cost, so that a company or a person may make as much money as it can. It has grown without any real thought for the human beings who tend the machines, and without the slightest consideration for what the artificial life imposed by the factory does to those workers and to their descendants. Our great cities have been raised with almost no regard for us. The height and dimensions of a skyscraper are decided entirely by the wish to squeeze the maximum rent out of every square foot of ground, and to offer tenants the kind of offices and apartments that will attract them. In this way enormous, monstrous towers have been thrown up, towers where far too many people are packed together. Civilized men seem to enjoy such a way of living. While they take pleasure in the comfort and the cheap luxury of their rooms, they never notice that they have been deprived of the true necessities of life. The modern city, in the end, is little more than a mass of huge buildings and dark, narrow streets, choked with the toxic fumes of countless engines, shaken by the endless roar of cars and buses, and thronged from morning to night by restless crowds. Plainly, it has not been planned for the good of the people who must live in it.","explanation_cn":"录音说现代城市显然不是为住在其中的居民的福祉而规划的。✓ the inhabitants."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l16',10,NULL,'choice','{"stem":"What fills the streets of the modern city, according to the speaker?","options":["Trees and gardens","Toxic fumes and the endless roar of traffic","Wide open spaces","Fresh air and quiet"],"answer_index":1,"audio":"When we organize our industrial life, we almost entirely forget the effect that the factory has on the body and mind of the men and women who work in it. Modern industry rests on a single idea: the greatest possible output at the lowest possible cost, so that a company or a person may make as much money as it can. It has grown without any real thought for the human beings who tend the machines, and without the slightest consideration for what the artificial life imposed by the factory does to those workers and to their descendants. Our great cities have been raised with almost no regard for us. The height and dimensions of a skyscraper are decided entirely by the wish to squeeze the maximum rent out of every square foot of ground, and to offer tenants the kind of offices and apartments that will attract them. In this way enormous, monstrous towers have been thrown up, towers where far too many people are packed together. Civilized men seem to enjoy such a way of living. While they take pleasure in the comfort and the cheap luxury of their rooms, they never notice that they have been deprived of the true necessities of life. The modern city, in the end, is little more than a mass of huge buildings and dark, narrow streets, choked with the toxic fumes of countless engines, shaken by the endless roar of cars and buses, and thronged from morning to night by restless crowds. Plainly, it has not been planned for the good of the people who must live in it.","explanation_cn":"录音说现代城市的街道被无数引擎的毒气窒塞、被车辆没完没了的轰鸣震动。✓ toxic fumes and roar of traffic."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
